using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
            ],
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"));
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsMeetThreshold(threshold: 3.0);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsGroundedAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsMeetThreshold(threshold: 3.0);
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(MultiTurnConversation_MaintainsCoherence));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan."),
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What are some must-see places?"));
        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsMeetThreshold(threshold: 3.0);
    }
}

